const listContracts = `-- name: ListContracts :many
SELECT c.id, d.number, d.status, c.parent_id, p.number AS parent_number, t.name AS contract_type_name,
       c.start_date, c.end_date, c.employee_id, e.code AS employee_code, e.full_name AS employee_name,
       count(*) OVER () AS total
FROM hrm.contracts c
JOIN record.documents d ON d.id = c.id
JOIN hrm.contract_types t ON t.id = c.contract_type_id
JOIN hrm.employees e ON e.id = c.employee_id
LEFT JOIN record.documents p ON p.id = c.parent_id
WHERE ($1::bool OR d.org_unit_id = ANY($2::bigint[]))
  AND ($3::text = '' OR d.status = $3)
  AND ($4::bigint IS NULL OR c.contract_type_id = $4)
  AND ($5::bigint IS NULL OR d.org_unit_id = $5)
  AND ($6::bigint IS NULL OR c.employee_id = $6)
  AND (NOT $7::bool OR (c.parent_id IS NULL AND d.status = 'posted'
       AND c.end_date BETWEEN $8::date AND $8::date + 30))
ORDER BY
    CASE WHEN $9::text = 'start_date' THEN c.start_date END,
    CASE WHEN $9 = '-start_date' THEN c.start_date END DESC,
    CASE WHEN $9 = 'end_date' THEN c.end_date END,
    CASE WHEN $9 = '-end_date' THEN c.end_date END DESC NULLS LAST,
    CASE WHEN $9 = 'number' THEN d.number END,
    CASE WHEN $9 = '-number' THEN d.number END DESC,
    c.id DESC
LIMIT $11 OFFSET $10
`

type ListContractsParams struct {
	AllUnits       bool
	Units          []int64
	Status         string
	ContractTypeID pgtype.Int8
	OrgUnitID      pgtype.Int8
	EmployeeID     pgtype.Int8
	Expiring       bool
	Today          pgtype.Date
	Sort           string
	Off            int32
	Lim            int32
}

type ListContractsRow struct {
	ID               int64
	Number           string
	Status           string
	ParentID         pgtype.Int8
	ParentNumber     pgtype.Text
	ContractTypeName string
	StartDate        pgtype.Date
	EndDate          pgtype.Date
	EmployeeID       int64
	EmployeeCode     string
	EmployeeName     string
	Total            int64
}

// Every contract and appendix in scope. Expiring: posted originals ending from @today to @today + 30 days.
func (q *Queries) ListContracts(ctx context.Context, arg ListContractsParams) ([]ListContractsRow, error) {
	rows, err := q.db.Query(ctx, listContracts,
		arg.AllUnits,
		arg.Units,
		arg.Status,
		arg.ContractTypeID,
		arg.OrgUnitID,
		arg.EmployeeID,
		arg.Expiring,
		arg.Today,
		arg.Sort,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListContractsRow
	for rows.Next() {
		var i ListContractsRow
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.Status,
			&i.ParentID,
			&i.ParentNumber,
			&i.ContractTypeName,
			&i.StartDate,
			&i.EndDate,
			&i.EmployeeID,
			&i.EmployeeCode,
			&i.EmployeeName,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

