const payrollSourceDocs = `-- name: PayrollSourceDocs :many
SELECT d.doc_type, d.id, d.version FROM record.documents d
WHERE d.legal_entity_id = $1 AND d.status = 'posted' AND (
       (d.doc_type = 'hrm.contract' AND EXISTS (
            SELECT 1 FROM hrm.contracts c LEFT JOIN hrm.contracts p ON p.id = c.parent_id
            WHERE c.id = d.id AND c.start_date <= $2::date
              AND (coalesce(p.end_date, c.end_date) IS NULL OR coalesce(p.end_date, c.end_date) >= $3::date)))
    OR (d.doc_type = 'hrm.timesheet' AND EXISTS (SELECT 1 FROM hrm.timesheets t WHERE t.id = d.id AND t.period_start = $4::date))
    OR (d.doc_type = 'hrm.leave_request' AND EXISTS (
            SELECT 1 FROM hrm.leave_requests r WHERE r.id = d.id AND r.start_date <= $2 AND r.end_date >= $4))
    OR (d.doc_type = 'hrm.overtime_request' AND EXISTS (
            SELECT 1 FROM hrm.overtime_requests o WHERE o.id = d.id AND o.date BETWEEN $5::date AND $2)))
ORDER BY d.doc_type, d.id
`

type PayrollSourceDocsParams struct {
	LegalEntityID int64
	PeriodEnd     pgtype.Date
	PrevStart     pgtype.Date
	PeriodStart   pgtype.Date
	YearStart     pgtype.Date
}

type PayrollSourceDocsRow struct {
	DocType string
	ID      int64
	Version int32
}

// Posted documents of the legal entity a payroll of [@period_start, @period_end] reads: contracts
// and appendices in force over it, its timesheets and leave, and overtime since @year_start.
func (q *Queries) PayrollSourceDocs(ctx context.Context, arg PayrollSourceDocsParams) ([]PayrollSourceDocsRow, error) {
	rows, err := q.db.Query(ctx, payrollSourceDocs,
		arg.LegalEntityID,
		arg.PeriodEnd,
		arg.PrevStart,
		arg.PeriodStart,
		arg.YearStart,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PayrollSourceDocsRow
	for rows.Next() {
		var i PayrollSourceDocsRow
		if err := rows.Scan(&i.DocType, &i.ID, &i.Version); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

